package org.sleepwell.app;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Explicit foreground-only two-stage accelerometer calibration. Never starts tracking or audio. */
public final class MotionCalibrationActivity extends Activity {
    private final Handler handler=new Handler(Looper.getMainLooper());
    private MotionPort port;private MotionSettings.Factory settings;private MotionSettings.Version expected;
    private MotionCalibration.Capture capture;private MotionCalibration.Summary rest,move;private MotionCalibration candidate;private List<Double> measuredBins=List.of();private boolean hasCalibration;
    private boolean resumed,registered,loadingFailed;private long stillFinished;private String message="",token;private TextView status,countdown;private MotionCalibrationChart chart;private Button start,save;private MotionProfile saved=new MotionProfile(1);
    private final Runnable tick=new Runnable(){public void run(){if(capture!=null){long now=port.now();if(now>=capture.start+capture.duration){complete(now);return;}updateCapture(now);handler.postDelayed(this,100);}}};
    private final Runnable poll=this::observe;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);settings=MotionSettings.factory;port=MotionSensorActivity.ports.create(getApplicationContext());try{SharedPreferences prefs=settings.open(this);expected=new MotionSettings.Version(prefs);hasCalibration=prefs.contains(MotionSettings.CUSTOM);try{saved=MotionSettings.read(prefs);}catch(RuntimeException error){message=error.getMessage();}}catch(RuntimeException error){loadingFailed=true;message="Motion settings are unavailable. Nothing was changed.";}if(state!=null){String pending=state.getString("token");if(pending!=null&&PlanOperations.tokens().contains(pending))token=pending;else message="Calibration was interrupted. Start again; no capture or save was replayed.";}render();}
    @Override protected void onResume(){super.onResume();resumed=true;if(token==null)render();observe();}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Surface calibration",this::back);Design.space(body,12);Design.text(body,"Check movement response on the surface where you place your phone.",15,400,Design.MUTED);Design.space(body,12);Design.item(body,"phone","Saved profile",saved.label(),null);Design.space(body,12);Design.text(body,rest==null?"1 · Leave the phone still for 10 seconds":move==null?"2 · Gently move the phone for 5 seconds":"Review measured response",19,600,Design.INK);Design.space(body,8);Design.text(body,rest==null?"Put the phone in its usual sleeping position. Tap Start still capture, then leave it untouched.":move==null?"Keep the phone on the same surface. Tap Start movement capture, then make small, slow movements. Do not shake or lift it abruptly.":"The result changes interpretation for your next phone-movement recording only. Saved raw motion remains unchanged.",14,400,Design.MUTED);Design.space(body,12);countdown=Design.text(body,"",28,600,Design.BROWN);status=Design.text(body,message,13,500,Design.BROWN);Design.space(body,10);chart=new MotionCalibrationChart(this);body.addView(chart,new LinearLayout.LayoutParams(-1,Design.dp(this,140)));Design.text(body,"Actual filtered acceleration RMS · missing readings stay blank",11,400,Design.MUTED);
        if(rest!=null){Design.space(body,12);Design.item(body,"moon","Still P90",number(rest.p90)+" m/s² · "+rest.samples+" samples",null);}if(move!=null)Design.item(body,"motion","Movement median",number(move.median)+" m/s² · "+move.samples+" samples",null);
        if(candidate!=null){Design.space(body,8);Design.item(body,"check","Proposed sensitivity",number(candidate.gain)+"×",null);Design.text(body,"Interpretation threshold: "+number(.12/candidate.gain)+" m/s², between this still P90 and movement median.",12,400,Design.MUTED);}
        Design.space(body,14);Design.text(body,"A surface-response check, not validated sleep-stage or wake detection. Softer surfaces and different phone positions can change the signal.",12,400,Design.MUTED);if(hasCalibration)Design.item(body,"reset","Reset saved calibration","Use manual sensitivity",this::reset);LinearLayout footer=RecordUi.footer(body);start=Design.button(footer,capture!=null?"Cancel capture":candidate!=null?"Start again":rest==null?"Start still capture":"Start movement capture",false,()->{if(capture!=null){cancel("Capture cancelled. Start again.");render();}else if(candidate!=null){cancel("");render();}else begin();});save=Design.button(footer,token==null?"Save calibration":"Saving…",true,this::save);start.setEnabled(token==null&&!loadingFailed);save.setEnabled(candidate!=null&&token==null&&!loadingFailed);if(token!=null)RecordUi.enabled(body,false);if(capture!=null)updateCapture(port.now());else{countdown.setText(candidate!=null?"Ready to save":rest!=null?"Still capture complete":"10 s + 5 s");chart.data(measuredBins);}}
    private void begin(){if(!resumed||!hasWindowFocus()||loadingFailed||token!=null||capture!=null)return;if(!port.available()){message="No accelerometer is available. Use manual sensitivity.";render();return;}candidate=null;move=null;message="";long now=port.now();if(rest!=null&&(now<stillFinished||now-stillFinished>120000)){cancel("The still capture expired. Start the two-stage calibration again.");render();return;}MotionCalibration.Capture owned=new MotionCalibration.Capture(now,rest==null?MotionCalibration.STILL_MS:MotionCalibration.MOVE_MS);capture=owned;registered=true;try{boolean begun=port.begin((time,x,y,z,accuracy)->{if(!registered||!resumed||!hasWindowFocus()||capture!=owned)return;owned.sample(time,port.now(),x,y,z,accuracy);if(!owned.error.isEmpty()){cancel(owned.error);render();}});if(!begun){cancel("The motion sensor could not start. Try again or use manual sensitivity.");render();return;}}catch(RuntimeException failure){cancel("The motion sensor could not start. Try again or use manual sensitivity.");render();return;}render();handler.post(tick);}
    private void updateCapture(long now){if(capture==null)return;long remaining=Math.max(0,capture.duration-(now-capture.start));countdown.setText((remaining+999)/1000+" s");status.setText(capture.duration==MotionCalibration.STILL_MS?"Measuring still response…":"Measuring gentle movement…");chart.data(capture.bins());}
    private void complete(long now){MotionCalibration.Capture ended=capture;if(ended==null)return;capture=null;handler.removeCallbacks(tick);boolean closed=closePort();if(!closed){cancel("The sensor could not be released. Close this screen before trying again.");render();return;}try{MotionCalibration.Summary measured=ended.finish(now);if(rest==null){rest=measured;stillFinished=now;message="Still readings saved for this open calibration. Start the movement capture when ready.";}else{move=measured;candidate=MotionCalibration.derive(rest,move,System.currentTimeMillis());message="Measured separation accepted. Review the result before saving.";}measuredBins=ended.bins();render();}catch(RuntimeException invalid){cancel(invalid.getMessage());render();}}
    private boolean closePort(){registered=false;try{port.close();return true;}catch(RuntimeException failure){return false;}}
    private void cancel(String text){handler.removeCallbacks(tick);capture=null;rest=null;move=null;candidate=null;measuredBins=List.of();if(!closePort())text="Sensor cleanup failed. Close this screen before using calibration again.";if(text!=null&&!text.isEmpty())message=text;}
    private void save(){if(!resumed||!hasWindowFocus()||candidate==null||capture!=null||token!=null||loadingFailed)return;MotionCalibration value=candidate;MotionSettings.Version prior=expected;MotionSettings.Factory scope=settings;token=UUID.randomUUID().toString();String id=token;PlanOperations.start(this,id,app->{MotionSettings.saveCalibration(scope.open(app),value,prior);return null;});render();observe();}
    private void reset(){if(!resumed||!hasWindowFocus()||token!=null||loadingFailed)return;cancel("");MotionSettings.Version prior=expected;MotionSettings.Factory scope=settings;token=UUID.randomUUID().toString();PlanOperations.start(this,token,app->{MotionSettings.reset(scope.open(app),prior);return null;});render();observe();}
    private void observe(){if(!resumed||token==null)return;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{throw new IllegalStateException("The save request was interrupted. Review calibration again.");});if(!operation.done){handler.postDelayed(poll,75);return;}PlanOperations.forget(token);token=null;if(operation.error==null){setResult(RESULT_OK);finish();}else{message=operation.error;candidate=null;rest=null;move=null;render();}}
    private static String number(double value){return String.format(Locale.ROOT,"%.3f",value);}
    private void back(){if(token==null){cancel("");finish();}}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);if(capture!=null||rest!=null||candidate!=null)cancel("Calibration stopped when this screen was left. Start again; nothing was saved automatically.");else closePort();super.onPause();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);else if(capture!=null||rest!=null||candidate!=null){cancel("Calibration stopped when this screen lost focus. Start again.");if(token==null)render();}}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(token!=null)state.putString("token",token);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);closePort();super.onDestroy();}
}
